<script setup lang="ts">
import {localize} from './localization';

import ZoomViewport from './ZoomViewport.vue';
import {computed,ref,watch} from 'vue';import {useSession} from './store';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh'),textureId=ref(''),textures=computed(()=>store.data.project?.surface?.textures??[]),texture=computed(()=>textures.value.find(t=>t.id===textureId.value)??textures.value[0]),seed=ref({x:0,y:0}),tolerance=ref(40),working=ref(false);
watch(()=>texture.value?.id,()=>{const t=texture.value;if(t)seed.value={x:t.width/2,y:t.height/2};},{immediate:true});
function pick(e:PointerEvent){const image=e.currentTarget as SVGSVGElement,t=texture.value,m=image.getScreenCTM();if(!t||!m||store.busy)return;const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse());if(p.x<0||p.y<0||p.x>=t.width||p.y>=t.height)return;seed.value={x:p.x,y:p.y};}
async function extract(){const p=store.data.project,t=texture.value;if(!p||!t)return;working.value=true;try{await store.run(()=>window.fpcad.textureMarking(p.id,p.revision,t.id,{...seed.value},tolerance.value));}finally{working.value=false;}}
async function cancel(){const p=store.data.project;if(p)await window.fpcad.cancelSurface(p.id,p.revision);}
</script>
<template><details v-if="textures.length" class="texture-tools" open><summary>{{zh?'模型 UV 纹理花纹':localize('Model UV texture markings')}}</summary><p>{{zh?'先展开并采用裁片，再点击纹理上的颜色区域。区域沿原模型 UV 裁剪到每个三角面，再映射到二维裁片；相同 UV 的重复部位会同时映射。分割使用 512 px 代理，细小花纹请在裁片中复核和修正。':localize('Accept unwrapped patterns, then click a texture region. Original per-face UV coordinates map the region into every pattern, including repeated UV islands. Segmentation uses a 512px proxy; review fine detail.')}}</p><select v-model="textureId" aria-label="Model texture"><option v-for="t in textures" :key="t.id" :value="t.id">{{t.name}} · {{t.width}} × {{t.height}}</option></select><template v-if="texture"><ZoomViewport :key="texture.id" :view-box="`0 0 ${texture.width} ${texture.height}`" label="Texture canvas" :language="language" v-slot="{viewBox}"><svg class="texture-image" :viewBox="viewBox" :aria-label="texture.name" @pointerdown="pick"><image :href="texture.proxy.png" :width="texture.width" :height="texture.height"/><circle :cx="seed.x" :cy="seed.y" :r="Math.max(texture.width,texture.height)/80" fill="none" stroke="var(--studio-coral)"/></svg></ZoomViewport><small>{{zh?'种子像素':localize('Seed pixel')}} {{seed.x.toFixed(1)}}, {{seed.y.toFixed(1)}}</small><label>{{zh?'颜色容差':localize('Color tolerance')}}<input v-model.number="tolerance" type="number" min="0" max="442"></label><button :disabled="store.busy||!store.data.project?.bindings?.length" @click="extract">{{zh?'沿 UV 映射为裁片花纹':localize('Map UV region to pattern markings')}}</button><button v-if="working" @click="cancel">{{zh?'取消纹理映射':localize('Cancel texture mapping')}}</button></template></details></template>
<style scoped>.texture-tools{border-bottom:1px solid var(--border);padding:12px 0;margin-bottom:12px}.texture-image{display:block;width:100%;height:280px;max-width:100%;margin:12px auto;cursor:crosshair}.texture-tools p{line-height:1.7}.texture-tools small{display:block;margin:8px 0}.texture-tools button,.texture-tools select{width:100%}</style>
